def _v3_pnl_sync():
    """Per-hour paper PnL under the exact engine rule: earliest scan of the hour
    (the T-60 decision), top NO candidate by edge (no_edge>=0.10, cost in
    [0.10,0.90], dist>0), 1c/ctr flat fee, graded against the settlement mid
    from the grades log. Also per-hour Brier of v3 vs the market mid over every
    strike with a two-sided quote. Forward-only (snapshots start 2026-08-06);
    appends one row per newly-settled hour to V3_PNL_JSONL."""
    try:
        if not (os.path.exists(V3_QUOTES_JSONL) and os.path.exists(V3_GRADES_JSONL)):
            return
        done = set()
        if os.path.exists(V3_PNL_JSONL):
            with open(V3_PNL_JSONL) as f:
                for line in f:
                    try:
                        done.add(json.loads(line).get("hour_et"))
                    except Exception:
                        pass
        settle = {}
        with open(V3_GRADES_JSONL) as f:
            for line in f:
                try:
                    g = json.loads(line)
                    if g.get("settle_mid") is not None:
                        settle[g["hour_et"]] = float(g["settle_mid"])
                except Exception:
                    pass
        by_hour = {}
        with open(V3_QUOTES_JSONL) as f:
            for line in f:
                try:
                    r = json.loads(line)
                except Exception:
                    continue
                h = r.get("hour_et")
                if not h or h in done or h not in settle:
                    continue
                by_hour.setdefault(h, []).append(r)
        n_new = 0
        with open(V3_PNL_JSONL, "a") as f:
            for h in sorted(by_hour):
                mid = settle[h]
                rows = by_hour[h]
                by_ts = {}
                for r in rows:
                    by_ts.setdefault(r.get("ts") or "", []).append(r)
                first = by_ts[sorted(by_ts)[0]]          # earliest scan = T-60 decision
                cands = []
                for r in first:
                    if r.get("yes_bid_c") is None or not r.get("dist") or r["dist"] <= 0:
                        continue
                    yb = r["yes_bid_c"] / 100.0
                    no_cost = 1.0 - yb
                    no_edge = yb - float(r["p_yes"])
                    if no_edge >= 0.10 and 0.10 <= no_cost <= 0.90:
                        cands.append((no_edge, r, no_cost))
                trade = None
                pnl_c = None
                if cands:
                    _, r, no_cost = max(cands, key=lambda c: c[0])
                    no_won = mid < float(r["thr"])
                    pnl_c = round(((1.0 if no_won else 0.0) - no_cost - 0.01) * 100.0, 2)
                    trade = r["ticker"]
                two = [r for r in rows if r.get("yes_bid_c") is not None and r.get("yes_ask_c") is not None]
                bv = bm = None
                if two:
                    sv = sm = 0.0
                    for r in two:
                        y = 1.0 if mid >= float(r["thr"]) else 0.0
                        mp = (r["yes_bid_c"]+r["yes_ask_c"]) / 200.0
                        sv += (float(r["p_yes"]) - y) ** 2
                        sm += (mp - y) ** 2
                    bv, bm = round(sv / len(two), 4), round(sm / len(two), 4)
                f.write(json.dumps({
                    "hour_et": h, "settle_mid": mid, "n_quotes": len(rows),
                    "rule_trade": trade, "pnl_c": pnl_c,
                    "brier_v3": bv, "brier_mkt": bm}) + "\n")
                n_new += 1
        if n_new:
            print(f"[v3] pnl: +{n_new} settled hour(s)")
    except Exception as e:
        print(f"[v3] pnl sync note (non-fatal): {e}")
